using System.Windows.Forms;

public class MainForm : Form
{
    private StatusStrip statusStrip;

    public MainForm()
    {
        statusStrip = new StatusStrip();
        // .NET 9: StatusStrip no longer defaults to System renderer.
        // Set explicitly to preserve .NET 8 appearance.
        statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(statusStrip);
    }
}

using System;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyEditor : UITypeEditor
{
    public override object? EditValue(
        ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService is null)
            return value;

        // .NET 9: DropDownControl parameter is now non-nullable.
        // Guard against null instead of passing it directly.
        Control? dropdown = CreateDropDown(value);
        if (dropdown is not null)
        {
            editorService.DropDownControl(dropdown);
            value = GetValueFromDropDown(dropdown);
        }

        return value;
    }

    private Control? CreateDropDown(object? currentValue)
    {
        // Build and return the dropdown control, or null if not applicable.
        return new ListBox();
    }

    private object? GetValueFromDropDown(Control dropdown)
    {
        if (dropdown is ListBox listBox)
            return listBox.SelectedItem;
        return null;
    }
}

